check_transformation_names.body:
{
        same("alpha source", &self.f.name, &self.alpha.source_functor)?;
        same("alpha target", &self.g.name, &self.alpha.target_functor)?;
        same("beta source", &self.h.name, &self.beta.source_functor)?;
